fn deps_of(deps: Map[Str, List[Str]], task: Str) -> List[Str] {
  let none: List[Str] = []
  return deps.get(task).unwrap_or(none)
}

fn is_ready(deps: Map[Str, List[Str]], task: Str, done: List[Str]) -> Bool {
  return deps_of(deps, task).all(fn(d) => done.contains(d))
}

pub fn topo(deps: Map[Str, List[Str]]) -> Result[List[Str], Str] {
  let names = deps.keys().concat(deps.values().flatten()).unique().sort()
  let total = names.len()
  var remaining: List[Str] = names
  var order: List[Str] = []
  while order.len() < total {
    let done_now = order
    let pick = remaining.find(fn(x) => is_ready(deps, x, done_now))
    match pick {
      Some(task) => {
        order = order.push(task)
        remaining = remaining.filter(fn(x) => x != task)
      },
      None => { return Err("cycle") },
    }
  }
  return Ok(order)
}
